<?php declare( strict_types=1 ); namespace Inc\Services\Exam; use Inc\Repositories\WPDBRepositories\ExamReportRepository; use Inc\Repositories\WPDBRepositories\ExamReportMemberRepository; class ExamReportService { private ExamReportRepository $reportRepo; private ExamReportMemberRepository $memberRepo; public function __construct( ?ExamReportRepository $reportRepo = null, ?ExamReportMemberRepository $memberRepo = null ) { $this->reportRepo = $reportRepo ?? new ExamReportRepository(); $this->memberRepo = $memberRepo ?? new ExamReportMemberRepository(); } public function createReport( int $eventId, string $title, int $ownerUserId, ?int $recipientSourceId = null ): int { return $this->reportRepo->insert( [ 'event_id' => $eventId, 'title' => $title, 'owner_user_id' => $ownerUserId, 'recipient_source_id' => $recipientSourceId, 'expires_at' => gmdate( 'Y-m-d H:i:s', time() + ( 30 * 86400 ) ), 'created_at' => current_time( 'mysql', true ), ] ); } public function addMemberToReport( int $reportId, int $participationId ): int { return $this->memberRepo->insert( [ 'report_id' => $reportId, 'participation_id' => $participationId, 'created_at' => current_time( 'mysql', true ), ] ); } public function getReportMembers( int $reportId ): array { return $this->memberRepo->findByReport( $reportId ); } public function revokeReport( int $reportId ): bool { return $this->reportRepo->update( $reportId, [ 'revoked_at' => current_time( 'mysql', true ), ] ); } }
